#include <bits/stdc++.h>
using namespace std;

static bool digitsAt(const string& s, initializer_list<int> pos) {
    for (int p : pos) if (!isdigit((unsigned char)s[p])) return false;
    return true;
}

static bool validUser(const string& u) {
    if (u.size() < 5 || u.compare(0, 4, "user") != 0) return false;
    string id = u.substr(4);
    if (id.size() > 10) return false;
    for (char c : id) if (!isdigit((unsigned char)c)) return false;
    return id == "0" || id[0] != '0';
}

static bool validTime(const string& t) {
    if (t.size() != 8 || t[2] != ':' || t[5] != ':' || !digitsAt(t, {0, 1, 3, 4, 6, 7})) return false;
    int h = stoi(t.substr(0, 2)), m = stoi(t.substr(3, 2)), s = stoi(t.substr(6, 2));
    return h < 24 && m < 60 && s < 60;
}

static bool validDate(const string& d) {
    if (d.size() != 10 || d[4] != '-' || d[7] != '-' || !digitsAt(d, {0, 1, 2, 3, 5, 6, 8, 9})) return false;
    int y = stoi(d.substr(0, 4)), m = stoi(d.substr(5, 2)), dd = stoi(d.substr(8, 2));
    if (y < 2000 || y > 3000 || m < 1 || m > 12 || dd < 1) return false;
    static const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    bool leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    int lim = days[m - 1] + (m == 2 && leap ? 1 : 0);
    return dd <= lim;
}

