import java.io.*;
import java.util.*;

public class Main {
    static boolean allDigits(String s, int... pos) {
        for (int p : pos) if (s.charAt(p) < '0' || s.charAt(p) > '9') return false;
        return true;
    }

    static boolean validUser(String u) {
        if (u.length() < 5 || !u.startsWith("user")) return false;
        String id = u.substring(4);
        if (id.length() > 10) return false;
        for (int i = 0; i < id.length(); i++) if (id.charAt(i) < '0' || id.charAt(i) > '9') return false;
        return id.equals("0") || id.charAt(0) != '0';
    }

    static boolean validTime(String t) {
        if (t.length() != 8 || t.charAt(2) != ':' || t.charAt(5) != ':' || !allDigits(t, 0, 1, 3, 4, 6, 7)) return false;
        int h = Integer.parseInt(t.substring(0, 2)), m = Integer.parseInt(t.substring(3, 5)), s = Integer.parseInt(t.substring(6, 8));
        return h < 24 && m < 60 && s < 60;
    }

    static boolean validDate(String d) {
        if (d.length() != 10 || d.charAt(4) != '-' || d.charAt(7) != '-' || !allDigits(d, 0, 1, 2, 3, 5, 6, 8, 9)) return false;
        int y = Integer.parseInt(d.substring(0, 4)), m = Integer.parseInt(d.substring(5, 7)), dd = Integer.parseInt(d.substring(8, 10));
        if (y < 2000 || y > 3000 || m < 1 || m > 12 || dd < 1) return false;
        int[] days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        boolean leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
        return dd <= days[m - 1] + (m == 2 && leap ? 1 : 0);
    }

    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        TreeMap<String, Integer> counts = new TreeMap<>((a, b) -> {
            String[] x = a.split(" "), y = b.split(" ");
            int c = x[0].compareTo(y[0]);
            return c != 0 ? c : x[1].compareTo(y[1]);
        });
        for (int i = 0; i < n; i++) {
            String u = st.nextToken(), t = st.nextToken(), d = st.nextToken();
            if (validUser(u) && validTime(t) && validDate(d)) counts.merge(u + " " + d, 1, Integer::sum);
        }
        StringBuilder sb = new StringBuilder().append(counts.size());
        for (Map.Entry<String, Integer> e : counts.entrySet()) sb.append('\n').append(e.getKey()).append(' ').append(e.getValue());
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func digitsAt(s string, pos ...int) bool {
	for _, p := range pos {
		if s[p] < '0' || s[p] > '9' {
			return false
		}
	}
	return true
}

func validUser(u string) bool {
	if len(u) < 5 || !strings.HasPrefix(u, "user") {
		return false
	}
	id := u[4:]
	if len(id) > 10 {
		return false
	}
	for i := 0; i < len(id); i++ {
		if id[i] < '0' || id[i] > '9' {
			return false
		}
	}
	return id == "0" || id[0] != '0'
}

func validTime(t string) bool {
	if len(t) != 8 || t[2] != ':' || t[5] != ':' || !digitsAt(t, 0, 1, 3, 4, 6, 7) {
		return false
	}
	h, _ := strconv.Atoi(t[0:2])
	m, _ := strconv.Atoi(t[3:5])
	s, _ := strconv.Atoi(t[6:8])
	return h < 24 && m < 60 && s < 60
}

func validDate(d string) bool {
	if len(d) != 10 || d[4] != '-' || d[7] != '-' || !digitsAt(d, 0, 1, 2, 3, 5, 6, 8, 9) {
		return false
	}
	y, _ := strconv.Atoi(d[0:4])
	m, _ := strconv.Atoi(d[5:7])
	dd, _ := strconv.Atoi(d[8:10])
	if y < 2000 || y > 3000 || m < 1 || m > 12 || dd < 1 {
		return false
	}
	days := []int{31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}
	lim := days[m-1]
	if m == 2 && ((y%4 == 0 && y%100 != 0) || y%400 == 0) {
		lim++
	}
	return dd <= lim
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	type key struct{ u, d string }
	counts := map[key]int{}
	for i := 0; i < n; i++ {
		u, t, d := next(), next(), next()
		if validUser(u) && validTime(t) && validDate(d) {
			counts[key{u, d}]++
		}
	}
	keys := make([]key, 0, len(counts))
	for k := range counts {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].u != keys[j].u {
			return keys[i].u < keys[j].u
		}
		return keys[i].d < keys[j].d
	})
	var sb strings.Builder
	sb.WriteString(strconv.Itoa(len(keys)))
	for _, k := range keys {
		fmt.Fprintf(&sb, "\n%s %s %d", k.u, k.d, counts[k])
	}
	fmt.Println(sb.String())
}
